from typing import List

"""
Solution for: count-connected-components-in-lcm-graph
Problem ID: lcb_3680

Implement the function below.
"""

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        """
        Count number of connected components in the graph where an edge between i and j exists iff lcm(nums[i], nums[j]) <= threshold.
        """
        n = len(nums)
        parent = list(range(n))
        rank = [0]*n
        def find(x):
            while parent[x]!=x:
                parent[x]=parent[parent[x]]
                x=parent[x]
            return x
        def union(a,b):
            pa,pb=find(a),find(b)
            if pa==pb: return
            if rank[pa]<rank[pb]:
                parent[pa]=pb
            elif rank[pa]>rank[pb]:
                parent[pb]=pa
            else:
                parent[pb]=pa
                rank[pa]+=1
        val_to_idx = {v:i for i,v in enumerate(nums)}
        T = threshold
        present = [False]*(T+1)
        for v in nums:
            if v<=T:
                present[v]=True
        first = [-1]*(T+1)
        for val in range(1,T+1):
            if not present[val]:
                continue
            idx = val_to_idx[val]
            for m in range(val,T+1,val):
                if first[m]==-1:
                    first[m]=idx
                else:
                    union(idx, first[m])
        root_set=set()
        for i in range(n):
            root_set.add(find(i))
        return len(root_set)


